    uint64_t o1 = x >> 1;
    uint64_t o2 = o1 & 0x5555555555555555;
    uint64_t o3 = x - o2;
    uint64_t o4 = o3 & 0x3333333333333333;
    uint64_t o5 = (o3 >> 2) & 0x3333333333333333;
    uint64_t o7 = o4 + o5;
    uint64_t o8 = o7 >> 4;
    uint64_t o9 = o8 + o7;
    return o9 & 0x0F0F0F0F0F0F0F0F;
}

